                                                            From.Add(D.ID);
                                                }
                                            }
                                            if (From != null)
                                            {
                                                if (From.Count > 0)
                                                {
                                                    byte Tries = (byte)Rnd.Next(0, From.Count);
                                                    ItemID = (uint)From[Tries];
                                                }
                                            }
                                            if (ItemID != 0)
                                            {
                                                I2.ID = ItemID;
                                                if (I2.DBInfo.LevReq != 1)
                                                {
                                                    ItemIDManipulation E = new ItemIDManipulation(ItemID);
                                                    E.QualityChange(Q);
                                                    I2.ID = E.ToID();
                                                }

                                                I2.Color = Item.ArmorColor.Orange;

                                                //I2.Plus = 3;
                                                if (Control == 5)
                                                {
                                                    I2.Plus = 2;
                                                }
                                                //else
