                                }
                                else if (Control == 4)
                                {
                                    GC.AddSend(Packets.NPCSay("Pick the two-handed weapon proficiency you would like to upgrade:"));
                                    GC.AddSend(Packets.NPCLink("Glaive", 110));
                                    GC.AddSend(Packets.NPCLink("LongHammer", 140));
                                    GC.AddSend(Packets.NPCLink("Halbert", 180));
                                    GC.AddSend(Packets.NPCLink("Pickaxe", 162));
                                    GC.AddSend(Packets.NPCLink("Previous Page", 2));
                                    GC.AddSend(Packets.NPCSetFace(65));
                                    GC.AddSend(Packets.NPCFinish());
                                }
                                #region Upgrade
                                else if (Control > 4)
                                {
                                    ushort WeaponId = (ushort)(Control + 400);//Club

                                    switch (Control)
                                    {
                                        case 5:
                                            WeaponId = 000;
                                            goto top;
                                        case 6:
                                            WeaponId = 900;
                                            goto top;
                                        case 40://whip
                                        case 60://hammer
                                        case 81://scepter
                                        case 90://dagger
                                        case 80://club
                                        case 20://Sword ,BS=421
                                        case 10://Blade
                                        case 21://BackSword
                                        case 30://Hook
                                        case 50://Axe
                                        case 100://Bow
                                        case 161://Wand
                                        case 160://Spear
                                        case 130://Poleaxe
                                        case 110://Glaive
                                        case 140://LongHammer
                                        case 180://Halbert
                                        case 162://Pickaxe
                                        top: if (!GC.MyChar.Profs.ContainsKey(WeaponId))
                                            {
                                                GC.AddSend(Packets.NPCSay("Your weapon proficiency must be at least level 1!"));
                                                GC.AddSend(Packets.NPCLink("I see", 255));
                                                GC.AddSend(Packets.NPCSetFace(65));
                                                GC.AddSend(Packets.NPCFinish());
                                                break;
                                            }
                                            Prof P = (Prof)GC.MyChar.Profs[WeaponId];
                                            #region ProficiencyTokens Price
                                            byte Price;

                                            if (P.Lvl < 3)
                                                Price = 1;
                                            else if (P.Lvl > 2 && P.Lvl < 6)
                                                Price = 2;
                                            else if (P.Lvl > 5 && P.Lvl < 8)
                                                Price = 3;
                                            else if (P.Lvl > 7 && P.Lvl < 10)
                                                Price = Convert.ToByte((P.Lvl - 4));
                                            else if (P.Lvl > 9 && P.Lvl < 12)
                                                Price = Convert.ToByte((P.Lvl - 3));
                                            else if (P.Lvl == 12)
                                                Price = 10;
                                            else if (P.Lvl > 12 && P.Lvl < 16)
                                                Price = Convert.ToByte((P.Lvl));
                                            else
                                                Price = Convert.ToByte((P.Lvl + 1) * 2);
                                            #endregion
                                            #region Upgrade
                                            if (GC.MyChar.Profs.ContainsKey(WeaponId))
                                            {
                                                if (P.Lvl >= 17)
                                                {
                                                    GC.AddSend(Packets.NPCSay("I'm sorry for your weapon proficiency is too high for me to help you! You must do it by yourself from now on!"));
                                                    GC.AddSend(Packets.NPCLink("I see", 255));
                                                    GC.AddSend(Packets.NPCSetFace(65));
                                                    GC.AddSend(Packets.NPCFinish());
                                                }
                                                else if (GC.Agreed && GC.MyChar.InventoryContains(722384, Price))
                                                {
                                                    GC.Agreed = false;
                                                    for (int i = 0; i < Price; i++)
                                                    {
                                                        GC.MyChar.RemoveItem(GC.MyChar.NextItem(722384));
                                                    }
                                                    P.Lvl++;
                                                    P.Exp = 0;
                                                    GC.AddSend(Packets.Prof(P));
                                                    GC.AddSend(Packets.NPCSay("Congratulations! Your proficiency has been upgraded!"));
                                                    GC.AddSend(Packets.NPCLink("Thanks", 255));
                                                    GC.AddSend(Packets.NPCSetFace(65));
                                                    GC.AddSend(Packets.NPCFinish());
                                                }
                                                else if (GC.Agreed && !GC.MyChar.InventoryContains(722384, Price))
                                                {
                                                    GC.Agreed = false;
                                                    GC.AddSend(Packets.NPCSay("I'm sorry but you don't have enough ProfiencyTokens!"));
                                                    GC.AddSend(Packets.NPCLink("I see", 255));
                                                    GC.AddSend(Packets.NPCSetFace(65));
                                                    GC.AddSend(Packets.NPCFinish());
                                                }
                                                else
                                                {
                                                    GC.AddSend(Packets.NPCSay("I will need " + Price + " ProficiencyTokens to updrage your weapon proficiency to " + (P.Lvl + 1) + "! Would you like to continue?"));
                                                    GC.AddSend(Packets.NPCLink("Yeah", Control));
                                                    GC.AddSend(Packets.NPCLink("Nevermind", 255));
                                                    GC.AddSend(Packets.NPCSetFace(65));
                                                    GC.AddSend(Packets.NPCFinish());
                                                    GC.Agreed = true;
                                                }

                                            }
                                            #endregion
                                            break;
                                    }
                                }
                                #endregion
                                break;
                            }
