                        #region Lab4 Exit - check
                        case 1156:
                            {
                                if (Control == 0)
                                {
                                    GC.AddSend(Packets.NPCSay("Hello, I see that you are a great warrior! Would you like me to take you to TwinCity?"));
                                    GC.AddSend(Packets.NPCLink("Take me to TwinCity", 1));
                                    GC.AddSend(Packets.NPCLink("I'll stay here for a while", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                }
                                else if (Control == 1)
                                {
                                    GC.MyChar.Teleport(1002, 431, 379);
                                }
                                break;
                            }
                        #endregion
                        #region Online Points Exchange - Check
                        case 6666:
                            {
                                if (Control == 0)
                                {
                                    GC.AddSend(Packets.NPCSay("As you have probably heard already, active players will have benefits. You'll will online points at random times for being online. Later on, the points can be exchanged by rewards! How cool is that?"));
                                    GC.AddSend(Packets.NPCLink("Check my Online Points", 1));
                                    GC.AddSend(Packets.NPCLink("Exchange for rewards", 2));
                                    GC.AddSend(Packets.NPCLink("Just passing by", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                }
                                else if (Control == 1) // trade cloud diamonds in
                                {
                                    GC.AddSend(Packets.NPCSay("Currently you have " + GC.MyChar.ClassicPoints + " Online Points! Make sure you keep your account logged in so you can exchange them for rewards!"));
                                    GC.AddSend(Packets.NPCLink("Thanks", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());

                                }
                                else if (Control == 2)
                                {
                                    GC.AddSend(Packets.NPCSay("What would you like to exchange your Online Points for?"));
                                    GC.AddSend(Packets.NPCLink("Double Experience (3)", 3));
                                    GC.AddSend(Packets.NPCLink("Better drops (3)", 4));
                                    GC.AddSend(Packets.NPCLink("5,000 Virtue Points (5)", 5));
                                    GC.AddSend(Packets.NPCLink("Random reward (6)", 6));
                                    GC.AddSend(Packets.NPCLink("Broadcast (5)", 7));
                                    GC.AddSend(Packets.NPCLink("Nevermind", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                }
                                else if (Control == 3)
                                {
                                    if (GC.MyChar.ClassicPoints >= 3)
                                    {
                                        GC.MyChar.ClassicPoints -= 3;
                                        GC.MyChar.ExpPotionUsed = DateTime.UtcNow;
                                        GC.MyChar.DoubleExp = true;
                                        GC.MyChar.DoubleExpLeft = 3600;
                                        GC.MyChar.MyClient.AddSend(Packets.Status(GC.MyChar.EntityID, Status.DoubleExpTime, (ulong)GC.MyChar.DoubleExpLeft));
                                        GC.AddSend(Packets.NPCSay("Congratulations! You have received 1 Hour of Double Experience!"));
                                        GC.AddSend(Packets.NPCLink("Thanks", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("You don't have enough Online Points!"));
                                        GC.AddSend(Packets.NPCLink("I see", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                }
                                else if (Control == 4)
                                {
                                    if (GC.MyChar.ClassicPoints >= 3)
                                    {
                                        GC.MyChar.ClassicPoints -= 3;
                                        GC.MyChar.LuckyTime = 3600;
                                        GC.MyChar.MyClient.AddSend(Packets.Status(GC.MyChar.EntityID, Status.LuckyTime, (ulong)GC.MyChar.LuckyTime));
                                        GC.AddSend(Packets.NPCSay("Congratulations! Your drops are increased for the next hour! Make sure you make the best out of it!"));
                                        GC.AddSend(Packets.NPCLink("Thanks", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("You don't have enough Online Points!"));
                                        GC.AddSend(Packets.NPCLink("I see", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                }
                                else if (Control == 5)
                                {
                                    if (GC.MyChar.ClassicPoints >= 5)
                                    {
                                        GC.MyChar.ClassicPoints -= 5;
                                        GC.MyChar.VP += 5000;
