                        #region Cathy - Daily Quests (Birdisland) - Adapted
                        case 6669:
                            {
                                bool questcomplete = false;
                                if ((GC.MyChar.BI_Quest_Kills >= 15000) && GC.MyChar.BI_Quest != 0)
                                {
                                    questcomplete = true;
                                }

                                if (Control == 0)
                                {
                                    if (questcomplete)
                                    {
                                        GC.AddSend(Packets.NPCSay("You're back! Are you finished already?"));
                                        GC.AddSend(Packets.NPCLink("I'm finished!", 10));
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("We are being overrun with monsters! Please help us purify our beautiful islands. I'll give you a nice reward if you do a job for me. Interested?"));
                                        GC.AddSend(Packets.NPCLink("Yes, tell me.", 2));
                                    }
                                    GC.AddSend(Packets.NPCLink("No thanks.", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                }

                                if (Control == 2)
                                {
                                    GC.AddSend(Packets.NPCSay("Kill 15,000 monsters for me, Birdmen Hawkings or BanditL97s. You can mix them up if you want to!"));
                                    GC.AddSend(Packets.NPCLink("Yes I'll do it.", 3));
                                    GC.AddSend(Packets.NPCLink("No thanks.", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                }

                                if (Control == 3)
                                {
                                    if (GC.MyChar.BI_Quest != 1)
                                    {
                                        GC.MyChar.BI_Quest = 1;
                                        GC.MyChar.BI_Quest_Kills = 0;
                                        GC.AddSend(Packets.NPCSay("Thank you! Type /quests to check your status and come see me when you're done. Hurry! If you disconnect, you have to start again!"));
                                        GC.AddSend(Packets.NPCLink("Okay.", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("I already gave you a job to do! type /quests to check your status and come see me when you're done. Hurry!"));
                                        GC.AddSend(Packets.NPCLink("Okay.", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                }

