                        #region Stage 2 - Check
                        case 3299:
                            {
                                if (Control == 0)
                                {
                                    if (GC.MyChar.DisCityMobs < GC.MyChar.DisToKill)
                                    {
                                        GC.AddSend(Packets.NPCSay("You'll pass if you kill " + GC.MyChar.DisToKill + " monsters in HellHall. Hurry up you got " + (GC.MyChar.DisToKill - GC.MyChar.DisCityMobs) + " monsters left to kill! Only 30 persons can geet to HellCloister with me."));
                                        GC.AddSend(Packets.NPCLink("I see", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("You've killed the " + GC.MyChar.DisToKill + " monsters, and you can pass to the HellCloister. Hurry up! What flank do you want to go in?"));
                                        GC.AddSend(Packets.NPCLink("Left flank.", 1));
                                        GC.AddSend(Packets.NPCLink("Right flank.", 2));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                }
                                else if (Control == 1)
                                {
                                    if (World.Dis3 < 30)
                                    {
                                        if (World.H_LeftFlank.Count < 15)
                                        {
                                            GC.MyChar.Teleport(2023, 297, 649);
                                            if (!World.H_LeftFlank.Contains(GC.MyChar.EntityID))
                                                World.H_LeftFlank.Add(GC.MyChar.EntityID, GC.MyChar);
                                            if (GC.MyChar.Level < 130)
                                                GC.MyChar.IncreaseExp(GC.MyChar.ExpBallExp * 2, false, false);
                                            
                                            World.Dis3 += 1;
                                            World.LeftFlank += 1;
                                            GC.MyChar.DisToKill = 0;
                                            if (World.Dis3 < 4)
                                                World.SendMsgToAll("SYSTEM", GC.MyChar.Name + " has passed through the HellHall and has entered into the HellCloister, ranked " + World.Dis3 + "!", 2011, 0);
                                            else
                                                World.SendMsgToAll("SYSTEM", GC.MyChar.Name + " has entered into the left flank of the HellCloister, ranked " + World.LeftFlank + "!", 2011, 0);
                                        }
                                        else
                                        {
                                            GC.AddSend(Packets.NPCSay("I'm sorry but this flank is full."));
                                            GC.AddSend(Packets.NPCLink("Oh damn...", 255));
                                            GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                            GC.AddSend(Packets.NPCFinish());
                                        }
                                    }
                                    else
                                    {
                                        foreach (Character C in World.H_Chars.Values)
                                        {
                                            if (C.Loc.Map == 2022)
                                            {
                                                C.Teleport(1020, 566, 564);
                                                GC.AddSend(Packets.NPCSay("Sorry but all the 30 places were taken. Come back next time."));
                                                GC.AddSend(Packets.NPCLink("Oh damn...", 255));
                                                GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                                GC.AddSend(Packets.NPCFinish());
                                            }
                                        }
                                        World.Dis3 = 0;
                                        World.LeftFlank = 0;
                                        World.RightFlank = 0;
                                    }
                                }
                                else if (Control == 2)
                                {
                                    if (World.Dis3 < 30)
                                    {
                                        if (World.H_RightFlank.Count < 15)
                                        {
                                            GC.MyChar.Teleport(2023, 297, 649);
                                            GC.MyChar.DisToKill = 0;
                                            if (GC.MyChar.Level < 130)
                                                GC.MyChar.IncreaseExp(GC.MyChar.ExpBallExp * 2, false, false);
                                            World.H_RightFlank.Add(GC.MyChar.EntityID, GC.MyChar);
                                            World.Dis3 += 1;
                                            World.RightFlank += 1;
                                            if (World.Dis3 < 4)
                                                World.SendMsgToAll("SYSTEM", GC.MyChar.Name + " has passed through the HellHall and has entered into the HellCloister, ranked " + World.Dis3 + "!", 2011, 0);
                                            else
                                                World.SendMsgToAll("SYSTEM", GC.MyChar.Name + " has entered into the right flank of the HellCloister, ranked " + World.RightFlank + "!", 2011, 0);
                                        }
                                        else
                                        {
                                            GC.AddSend(Packets.NPCSay("I'm sorry but this flank is full."));
                                            GC.AddSend(Packets.NPCLink("Oh damn...", 255));
                                            GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                            GC.AddSend(Packets.NPCFinish());
                                        }
                                    }
                                    else
                                    {
                                        foreach (Character C in World.H_Chars.Values)
                                        {
                                            if (C.Loc.Map == 2022)
                                            {
                                                C.Teleport(1020, 566, 564);
                                                GC.AddSend(Packets.NPCSay("Sorry but all the 30 places were taken. Come back next time."));
                                                GC.AddSend(Packets.NPCLink("Oh damn...", 255));
                                                GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                                GC.AddSend(Packets.NPCFinish());
                                            }
                                        }
                                        World.Dis3 = 0;
                                        World.LeftFlank = 0;
                                        World.RightFlank = 0;
                                    }
                                }
                                break;
                            }
