                        #region Stage4 Reward - Check
                        case 3300:
                            {
                                if (Control == 0)
                                {
                                    if (GC.MyChar.InventoryContains(790001, 1))
                                    {
                                        GC.AddSend(Packets.NPCSay("Hooray! Thanks to you " + GC.MyChar.Name + " Ultimate Pluto has been defeated! Here take this Sword and see me in Ape Mountain for the reward!"));
                                        GC.AddSend(Packets.NPCLink("Thanks!", 1));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("Hurry up and kill Ultimate Pluto! Don't forget to bring the Dark Horn!"));
                                        GC.AddSend(Packets.NPCLink("Ok.!", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                }
                                else if (Control == 1)
                                {
                                    GC.MyChar.RemoveItem(GC.MyChar.NextItem(790001));
                                    GC.MyChar.AddItem(723088);
                                    GC.AddSend(Packets.NPCSay("Here you are!"));
                                    GC.AddSend(Packets.NPCLink("Thanks", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                    foreach (Character C in World.H_Chars.Values)
                                    {
                                        if (C.Loc.Map == 2024 || C.Loc.Map == 2023 || C.Loc.Map == 2022 || C.Loc.Map == 2021)
                                            C.Teleport(1020, 566, 564);
                                    }
                                    World.SendMsgToAll("SYSTEM", GC.MyChar.Name + " has delivered the DarkHorn to SolarSaint and DisCity has ended!", 2011, 0);
                                }
                                break;
                            }
