                        #region World Events
                        case 2053:
                            {
                                if (Control == 0)
                                {
                                    GC.AddSend(Packets.NPCSay("Howdy! I was sent to this earth to promote companionship within the server! One can pay a tribute in order to achieve a common goal that will reward the whole server!"));
                                    GC.AddSend(Packets.NPCLink("I'd like contribute", 1));
                                    GC.AddSend(Packets.NPCLink("Just passing by.", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                    GC.ER = false;
                                    GC.DR = false;
                                }
                                else if (Control == 1)
                                {
                                    GC.AddSend(Packets.NPCSay("Alright! I'm glad to know that you're willing to help! What would you like to contribute to?"));
                                    GC.AddSend(Packets.NPCLink("2x EXP (" + World.ERPts + " Pts left)", 2));
                                    GC.AddSend(Packets.NPCLink("25% Drop Rates (" + World.DRPts + " Pts left)", 4));
                                    GC.AddSend(Packets.NPCLink("Just passing by.", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                }
                                else if (Control == 2 || Control == 4)
                                {
                                    if (Control == 2)
                                    {
                                        GC.AddSend(Packets.NPCSay("Awesome! There are " + World.ERPts + " points left to activate 1 hour of 2x EXP Rate! What would you like to contribute with?"));
                                        GC.ER = true;
                                    }
                                    else if (Control == 4)
                                    {
                                        GC.AddSend(Packets.NPCSay("Awesome! There are " + World.DRPts + " points left to activate 1 hour of 25% higher drop rates! What would you like to contribute with?"));
                                        GC.DR = true;
                                    }
                                    GC.AddSend(Packets.NPCLink("MeteorScroll (10 Points)", 10));
                                    GC.AddSend(Packets.NPCLink("DragonBall (10 Points)", 20));
                                    GC.AddSend(Packets.NPCLink("MetscrollBag (100 Points)", 100));
                                    GC.AddSend(Packets.NPCLink("DBScroll (100 Points)", 200));
                                    GC.AddSend(Packets.NPCLink("Super Gem (100 Points)", 14));
                                    GC.AddSend(Packets.NPCLink("Just passing by.", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                }
                                else if (Control == 14)
                                {
                                    GC.AddSend(Packets.NPCSay("Each Super Gem equals 100 Points! Which Super Gem would you like to contribute?"));
                                    GC.AddSend(Packets.NPCLink("Dragon Gem", 13));
                                    GC.AddSend(Packets.NPCLink("Phoenix Gem", 3));
                                    GC.AddSend(Packets.NPCLink("Violet Gem", 53));
                                    GC.AddSend(Packets.NPCLink("Rainbow Gem", 33));
                                    GC.AddSend(Packets.NPCLink("Moon Gem", 63));
                                    GC.AddSend(Packets.NPCLink("Kylin Gem", 43));
                                    GC.AddSend(Packets.NPCLink("Fury Gem", 23));
                                    GC.AddSend(Packets.NPCLink("I changed my mind", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                }
                                else if (Control == 10 || Control == 20 || Control == 100 || Control == 200 || Control == 13 || Control == 3 || Control == 53 || Control == 33 || Control == 63 || Control == 43 || Control == 23)
                                {
                                    uint ID = 0;
                                    if (Control == 10)
                                        ID = 720027;
                                    else if (Control == 20)
                                        ID = 1088000;
                                    else if (Control == 100)
                                        ID = 729912;
                                    else if (Control == 200)
                                        ID = 720028;
                                    else if (Control % 10 == 3)
                                        ID = (700000 + Convert.ToUInt32(Control));
                                    Item IID = new Item();
                                    IID.ID = ID;
                                    if (GC.MyChar.InventoryContains(ID, 1))
                                    {
                                        GC.MyChar.RemoveItem(GC.MyChar.NextItem(ID));
                                        if (GC.ER)
                                        {
                                            if (Control % 10 == 3)
                                                Control = 100;
                                            else if (Control == 20)
                                                Control = 10;
                                            else if (Control == 200)
                                                Control = 100;
                                            if (World.ERPts > Control)
                                                World.ERPts -= Control;
                                            else
                                            {
                                                World.ERPts = 1000;
                                                World.EREvent = DateTime.UtcNow.AddMinutes(60);
                                                World.SendMsgToAll("SYSTEM", GC.MyChar.Name + " has made the final donation and activated global 2x EXP Rate for 1 hour! Enjoy!", 2011, 0);
                                            }
                                        }
                                        else if (GC.DR)
                                        {
                                            if (Control % 10 == 3)
                                                Control = 100;
                                            else if (Control == 20)
                                                Control = 10;
                                            else if (Control == 200)
                                                Control = 100;
                                            if (World.DRPts > Control)
                                                World.DRPts -= Control;
                                            else
                                            {
                                                World.DRPts = 1000;
                                                World.EREvent = DateTime.UtcNow.AddMinutes(60);
                                                World.SendMsgToAll("SYSTEM", GC.MyChar.Name + " has made the final donation and activated global 25% highe drop rates for 1 hour! Enjoy!", 2011, 0);
                                            }
                                        }
                                        GC.AddSend(Packets.NPCSay("Congratulations ! You've contributed to the global events with a " + IID.DBInfo.Name + " and donated " + Control + " Points!"));
                                        GC.AddSend(Packets.NPCLink("Thanks", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("It seems that you don't have a " + IID.DBInfo.Name + "! Please come back when you have it!"));
                                        GC.AddSend(Packets.NPCLink("I see", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                }
                                break;
                            }
