                                    {
                                        GC.AddSend(Packets.NPCSay("You have killed a wanted player and didn't receive your reward yet! Please claim it before taking another offer!"));
                                        GC.AddSend(Packets.NPCLink("Claim bounty reward", 9));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                    else
                                    {
                                        byte Pages = Convert.ToByte(World.Bounty.Count / 6);
                                        byte CurControl = 30;
                                        byte _static = 30;
                                        GC.AddSend(Packets.NPCSay("I'll keep 10% of the bounty for myself! Which bounty would you like to take?"));
                                        foreach (var Name in World.Bounty.OrderByDescending(s => s.Value))
                                        {
                                            if (CurControl >= (_static + (6 * GC.MyChar.Page)) && CurControl <= (_static + (6 * GC.MyChar.Page) + 5))
                                                GC.AddSend(Packets.NPCLink(Name.Key + " - " + Name.Value.ToString("#,#", System.Globalization.CultureInfo.InvariantCulture), CurControl));
                                            //Page 0: CurControl >= 30 && CurControl <= 34
                                            //Page 1: CurControl >= 35 && CurControl <= 39
                                            //Page 2: CurControl >= 40 && CurControl <= 44

                                            CurControl++;
                                        }
                                        if (Pages > GC.MyChar.Page)
                                            GC.AddSend(Packets.NPCLink("Next", 2));

                                        GC.AddSend(Packets.NPCLink("Nevermind", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                        GC.MyChar.Page++;
                                    }
                                }
                                else if (Control >= 30)
                                {
                                    byte Player = 30;
                                    foreach (string Name in World.Bounty.Keys)
                                    {
                                        if (Player == Control)
                                        {
                                            if (GC.Agreed)
                                            {
                                                GC.MyChar.OnBounty = Name;
                                                GC.AddSend(Packets.NPCSay("How much would you like to contribute with to " + GC.MyChar.OnBounty + "'s bounty?"));
                                                GC.AddSend(Packets.NPCLink2("Add:", 15));
                                                GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                                GC.AddSend(Packets.NPCFinish());
                                                GC.MyChar.KilledBounty = false;
                                                GC.Agreed = false;
                                            }
                                            else
                                            {
                                                if (Name == GC.MyChar.Name)
                                                {
                                                    GC.AddSend(Packets.NPCSay("You can't accept a bounty that's on you. Do you want to remove it?"));
                                                    GC.AddSend(Packets.NPCLink("Yeah", 3));
                                                    GC.AddSend(Packets.NPCLink("Nevermind", 255));
                                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                                    GC.AddSend(Packets.NPCFinish());
                                                    GC.MyChar.KilledBounty = false;
                                                }
                                                else
                                                {
                                                    GC.MyChar.OnBounty = Name;
                                                    GC.AddSend(Packets.NPCSay("You have accepted this bounty and you're now hunting " + GC.MyChar.OnBounty + "! You may come back to me after you kill him/her!"));
                                                    GC.AddSend(Packets.NPCLink("I will", 255));
                                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                                    GC.AddSend(Packets.NPCFinish());
                                                    GC.MyChar.KilledBounty = false;
                                                }
                                            }
                                        }
                                        Player++;
                                    }
                                }
                                else if (Control == 9)
                                {
                                    if (GC.MyChar.KilledBounty)
                                    {
                                        if (World.Bounty.ContainsKey(GC.MyChar.OnBounty))
                                        {
                                            if (GC.MyChar.Silvers <= (999999999 - Convert.ToUInt32(World.Bounty[GC.MyChar.OnBounty] * 0.9)))
                                            {
                                                GC.AddSend(Packets.NPCSay("You have received " + Convert.ToUInt32(World.Bounty[GC.MyChar.OnBounty] * 0.9).ToString("#,#", System.Globalization.CultureInfo.InvariantCulture) + " silvers for completing a job for me and killing " + GC.MyChar.OnBounty + "!"));
                                                GC.AddSend(Packets.NPCLink("Thanks", 255));
                                                GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                                GC.AddSend(Packets.NPCFinish());
                                                GC.MyChar.Silvers += Convert.ToUInt32(World.Bounty[GC.MyChar.OnBounty] * 0.9);
                                                World.Bounty.Remove(GC.MyChar.OnBounty);
                                                GC.MyChar.OnBounty = "";
                                                GC.MyChar.KilledBounty = false;
                                            }
                                        }
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("It seems like you didn't kill " + GC.MyChar.OnBounty + " yet! You may come back to me after you kill him/her!"));
                                        GC.AddSend(Packets.NPCLink("I will", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                }
                                else if (Control == 4)
                                {
                                    byte Pages = Convert.ToByte(World.Bounty.Count / 7);
                                    byte CurControl = 30;
                                    byte _static = 30;
                                    GC.AddSend(Packets.NPCSay("Which bounty would you like to contribute to?"));
                                    foreach (var Name in World.Bounty.OrderByDescending(s => s.Value))
                                    {
                                        if (CurControl >= (_static + (6 * GC.MyChar.Page)) && CurControl <= (_static + (6 * GC.MyChar.Page) + 5))
                                            GC.AddSend(Packets.NPCLink(Name.Key + " - " + Name.Value.ToString("#,#", System.Globalization.CultureInfo.InvariantCulture), CurControl));

                                        CurControl++;
                                    }
                                    if (Pages > GC.MyChar.Page)
                                        GC.AddSend(Packets.NPCLink("Next", 2));

                                    GC.AddSend(Packets.NPCLink("Nevermind", 255));
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                    GC.AddSend(Packets.NPCFinish());
                                    GC.MyChar.Page++;
                                    GC.Agreed = true;
                                }
                                else if (Control == 15)
                                {
                                    uint Money = Convert.ToUInt32(ReadString(Data));
                                    if (GC.MyChar.Silvers >= Money)
                                    {
                                        GC.MyChar.Silvers -= Money;
                                        World.Bounty[GC.MyChar.OnBounty] += Money;
                                        GC.AddSend(Packets.NPCSay("You have added " + Money.ToString("#,#", System.Globalization.CultureInfo.InvariantCulture) + " silvers to " + GC.MyChar.OnBounty + "'s bounty!"));
                                        GC.AddSend(Packets.NPCLink("Thanks", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                        GC.MyChar.OnBounty = "";
                                        GC.MyChar.KilledBounty = false;
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("You don't have enough silvers!"));
                                        GC.AddSend(Packets.NPCLink("I see", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                        GC.MyChar.OnBounty = "";
                                        GC.MyChar.KilledBounty = false;
                                    }
                                }
                                else if (Control == 3)
                                {
                                    if (World.Bounty.ContainsKey(GC.MyChar.Name))
                                    {
                                        GC.AddSend(Packets.NPCSay("You can remove the bounty that's on your head by paying me " + (World.Bounty[GC.MyChar.Name] * 2).ToString("#,#", System.Globalization.CultureInfo.InvariantCulture) + " silvers! Do you want to do it?"));
                                        GC.AddSend(Packets.NPCLink("Yeah", 16));
                                        GC.AddSend(Packets.NPCLink("Nevermind", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                    else
                                    {
                                        GC.AddSend(Packets.NPCSay("It seems like you don't have a bounty on your head..."));
                                        GC.AddSend(Packets.NPCLink("I see", 255));
                                        GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                        GC.AddSend(Packets.NPCFinish());
                                    }
                                }
                                else if (Control == 16)
                                {
                                    if (World.Bounty.ContainsKey(GC.MyChar.Name))
                                    {
                                        if (GC.MyChar.Silvers >= (World.Bounty[GC.MyChar.Name] * 2))
                                        {
                                            GC.MyChar.Silvers -= Convert.ToUInt32(World.Bounty[GC.MyChar.Name] * 2);
                                            World.Bounty.Remove(GC.MyChar.Name);
                                            GC.AddSend(Packets.NPCSay("You have successfully removed the bounty you had on your head!"));
                                            GC.AddSend(Packets.NPCLink("Great!", 255));
                                            GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                            GC.AddSend(Packets.NPCFinish());
                                        }
                                        else
                                        {
                                            GC.AddSend(Packets.NPCSay("It seems like you don't have enough money to cover the bounty on your head..."));
                                            GC.AddSend(Packets.NPCLink("I see", 255));
                                            GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                            GC.AddSend(Packets.NPCFinish());
                                        }
                                    }
                                }
                                break;
                            }
                        #endregion

                        default:
                            {
                                GC.AddSend(Packets.NPCSay("Hello there, my ID is " + NPC.ToString() + "! I'm not coded yet. Please report this to the STAFF team!"));
                                GC.AddSend(Packets.NPCLink("Ok", 255));
                                if (N != null)
                                    GC.AddSend(Packets.NPCSetFace(N.Avatar));
                                else
                                    GC.AddSend(Packets.NPCSetFace(30));
                                GC.AddSend(Packets.NPCFinish());
                                break;
                            }
                    }
                }
            }
            catch (Exception Exc) { Game.World.ExcAdd += Exc.ToString() + "\r\n"; }
        }
    }
}